-- Point products at their bundled photos in /public/products/<slug>.png.
-- Only the slugs that actually have an image file; the rest keep null (emoji fallback).
update products set image_url = '/products/' || slug || '.png' where slug in ('air-cooler','bath-mat','bathroom-shelf','bedding-set','blackout-curtain','blanket','broom-set','cleaning-cloth','clothes-rack','coffee-tea','cooking-oil','desk-lamp','detergent','dining-chairs','dining-table-round','dining-table-square','dish-rack','dish-soap','door-hanger','drinking-water','drying-rack','fabric-softener','fabric-wardrobe','floor-cleaner','food-containers','frying-pan','glass-cleaner','glasses','instant-noodles','kettle','kitchen-shelf','knife-board','laundry-rack','liquid-detergent','mattress-3-5ft','microwave','mini-fridge','mop-bucket','pillowcases','plates','power-strip','rice-5kg','rice-cooker','rice-spoon','rug','seasoning-set','sofa-bed','stand-fan','tall-shelf','toilet-cleaner','toiletries-set','towel-rack','towels','trash-bags','trash-bin','wood-wardrobe','work-chair','work-desk');
